import random
import statistics

def task_func(LETTERS):
    if not LETTERS:
        return {}

    letters = list(dict.fromkeys(LETTERS))
    selected_letters = random.sample(letters, random.randint(1, len(letters)))

    data = {
        letter: [random.randint(-100, 100) for _ in range(random.randint(1, 20))]
        for letter in selected_letters
    }

    return dict(
        sorted(
            data.items(),
            key=lambda item: statistics.mean(item[1]),
            reverse=True
        )
    )
